{
  "subtype": "causal_attribution",
  "outcome_variable": "resolution_time",
  "per_column": [
    {
      "name": "resolution_complexity",
      "causal_role": "treatment",
      "named_in_query": false,
      "rationale": "The nature/complexity of what must be done to resolve the ticket is a candidate underlying cause of longer resolution times -- a plausible treatment being attributed."
    },
    {
      "name": "issue_severity_signal",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Severity/type of issue plausibly drives both how complex/lengthy the resolution work is and the resolution time; a common cause not named in the query."
    },
    {
      "name": "recurrent_issue",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Whether an issue is recurrent can affect both the complexity/approach taken and the time to resolve; plausibly a common cause, surfaced from data."
    },
    {
      "name": "authentication_or_access_requirement",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Access/authentication involvement can shape both the resolution approach (treatment) and duration; not named in the query."
    },
    {
      "name": "hardware_or_software_installation_need",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Needing installation drives both the type of resolution work and the time; plausible common cause, but overlaps heavily with treatment definition."
    },
    {
      "name": "scope_of_impact",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Breadth of impact (company-wide vs single user) plausibly influences both the complexity of resolution effort and the duration; a genuine common cause not in the query."
    },
    {
      "name": "assigned_technician",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "The specific technician can affect which tickets they take (assignment/complexity) and their resolution speed; a plausible common cause surfaced from data."
    },
    {
      "name": "assigned_resolver_consistency",
      "causal_role": "mediator",
      "named_in_query": false,
      "rationale": "Whether the same resolver handled the ticket throughout is largely on the causal path from handling to duration; adjusting for it as a confounder is questionable."
    },
    {
      "name": "closure_status_completeness",
      "causal_role": "collider",
      "named_in_query": false,
      "rationale": "Closure completeness is an outcome/consequence of the resolution process, not a prior common cause; conditioning on it would induce bias."
    },
    {
      "name": "issue_category",
      "causal_role": "confounder",
      "named_in_query": true,
      "rationale": "Category is explicitly named as something to control for in the query; a stated confounder, not a surfaced one."
    }
  ],
  "treatment_present": true,
  "treatment_columns": ["resolution_complexity"],
  "confounders": [
    {"name": "issue_severity_signal", "named_in_query": false, "plausibility": 0.7},
    {"name": "recurrent_issue", "named_in_query": false, "plausibility": 0.55},
    {"name": "authentication_or_access_requirement", "named_in_query": false, "plausibility": 0.5},
    {"name": "hardware_or_software_installation_need", "named_in_query": false, "plausibility": 0.45},
    {"name": "scope_of_impact", "named_in_query": false, "plausibility": 0.7},
    {"name": "assigned_technician", "named_in_query": false, "plausibility": 0.6},
    {"name": "issue_category", "named_in_query": true, "plausibility": 0.6}
  ],
  "confounder_quality": 0.6,
  "rationale": "The added columns do set up a causal estimation: resolution_complexity acts as a candidate treatment/underlying cause of longer resolution_time, and several columns (issue_severity_signal, scope_of_impact, assigned_technician, recurrent_issue) are genuine common causes of both the resolution approach and duration that were surfaced from the data rather than copied from the query -- these demonstrate the capability under test. issue_category duplicates a control already named in the query and so does not count as a surfaced confounder. Two columns are problematic: assigned_resolver_consistency is closer to a mediator, and closure_status_completeness is a post-treatment consequence/collider whose inclusion as an adjustment variable would bias the attribution. Overall the set realises causal attribution moderately well, with several non-query confounders, but is diluted by mediator/collider inclusions and some overlap between treatment and confounder definitions."
}

